<template>
  <el-card>
    <div slot="header">
      <i class="el-icon-s-finance"></i> 收银结算
      <el-button size="mini" type="primary" plain style="float:right;" @click="refreshData">
        <i class="el-icon-refresh"></i> 刷新数据
      </el-button>
    </div>

    <!-- 今日汇总卡片 -->
    <el-row :gutter="16">
      <el-col :span="6">
        <el-card shadow="hover" class="stat-card">
          <div class="stat-inner">
            <div class="stat-icon" style="background:#409EFF;"><i class="el-icon-s-finance"></i></div>
            <div class="stat-info">
              <div class="stat-num">¥{{ todaySummary.totalIncome }}</div>
              <div class="stat-label">今日总收入</div>
            </div>
          </div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card shadow="hover" class="stat-card">
          <div class="stat-inner">
            <div class="stat-icon" style="background:#67C23A;"><i class="el-icon-postcard"></i></div>
            <div class="stat-info">
              <div class="stat-num">{{ todaySummary.regIncome }}</div>
              <div class="stat-label">挂号费收入</div>
            </div>
          </div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card shadow="hover" class="stat-card">
          <div class="stat-inner">
            <div class="stat-icon" style="background:#E6A23C;"><i class="el-icon-document-copy"></i></div>
            <div class="stat-info">
              <div class="stat-num">{{ todaySummary.drugCheckIncome }}</div>
              <div class="stat-label">药费+检查费收入</div>
            </div>
          </div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card shadow="hover" class="stat-card">
          <div class="stat-inner">
            <div class="stat-icon" style="background:#F56C6C;"><i class="el-icon-document"></i></div>
            <div class="stat-info">
              <div class="stat-num">{{ todaySummary.orderCount }}</div>
              <div class="stat-label">今日收费笔数</div>
            </div>
          </div>
        </el-card>
      </el-col>
    </el-row>

    <!-- 支付方式分布 -->
    <el-row :gutter="16" style="margin-top:16px;">
      <el-col :span="8">
        <el-card>
          <div slot="header"><i class="el-icon-pie-chart"></i> 支付方式分布</div>
          <div id="paymentPieChart" style="width:100%;height:280px;"></div>
        </el-card>
      </el-col>
      <el-col :span="16">
        <el-card>
          <div slot="header">
            <span><i class="el-icon-s-order"></i> 收费记录</span>
            <div style="float:right;">
              <el-select v-model="paymentFilter" size="mini" placeholder="支付方式" @change="filterRecords" style="width:120px;margin-right:8px;">
                <el-option label="全部" value=""></el-option>
                <el-option label="现金" value="现金"></el-option>
                <el-option label="微信" value="微信"></el-option>
                <el-option label="支付宝" value="支付宝"></el-option>
                <el-option label="银行卡" value="银行卡"></el-option>
                <el-option label="医保" value="医保"></el-option>
              </el-select>
              <el-button size="mini" type="primary" plain @click="exportCsv">
                <i class="el-icon-download"></i> 导出CSV
              </el-button>
              <el-button size="mini" type="success" plain @click="dailySettlement">
                <i class="el-icon-document-checked"></i> 日结
              </el-button>
            </div>
          </div>
          <el-table :data="filteredRecords" border stripe size="small" max-height="380" style="width:100%">
            <el-table-column prop="brId" label="编号" width="65" align="center"></el-table-column>
            <el-table-column prop="oId" label="订单号" width="75" align="center"></el-table-column>
            <el-table-column prop="brType" label="收费类型" width="100"></el-table-column>
            <el-table-column label="金额" width="90" align="center">
              <template slot-scope="s">¥{{ s.row.brAmount }}</template>
            </el-table-column>
            <el-table-column prop="brPaymentMethod" label="支付方式" width="80" align="center"></el-table-column>
            <el-table-column prop="brInvoiceNo" label="发票号" width="140"></el-table-column>
            <el-table-column prop="brPayTime" label="收费时间" width="155"></el-table-column>
            <el-table-column prop="brOperator" label="操作员" width="80" align="center"></el-table-column>
          </el-table>
          <div v-if="filteredRecords.length === 0" style="text-align:center;padding:30px;color:#999;">暂无收费记录</div>
        </el-card>
      </el-col>
    </el-row>

    <!-- 日结报告对话框 -->
    <el-dialog title="日结报告" :visible.sync="settlementDlgVisible" width="600px">
      <el-card shadow="hover" style="margin-bottom:15px;">
        <div slot="header"><span style="font-weight:bold;">结算概要</span></div>
        <el-descriptions :column="2" border size="small">
          <el-descriptions-item label="结算日期">{{ todayStr }}</el-descriptions-item>
          <el-descriptions-item label="结算时间">{{ nowTimeStr }}</el-descriptions-item>
          <el-descriptions-item label="收费总笔数">{{ todaySummary.orderCount }}</el-descriptions-item>
          <el-descriptions-item label="总收入">¥{{ todaySummary.totalIncome }}</el-descriptions-item>
          <el-descriptions-item label="挂号费">¥{{ todaySummary.regIncome }}</el-descriptions-item>
          <el-descriptions-item label="药费+检查费">¥{{ todaySummary.drugCheckIncome }}</el-descriptions-item>
        </el-descriptions>
      </el-card>
      <el-card shadow="hover" v-if="paymentBreakdown.length > 0">
        <div slot="header"><span style="font-weight:bold;">支付方式明细</span></div>
        <el-table :data="paymentBreakdown" border stripe size="small" style="width:100%">
          <el-table-column prop="method" label="支付方式" width="120"></el-table-column>
          <el-table-column prop="count" label="笔数" width="80" align="center"></el-table-column>
          <el-table-column label="金额" width="120" align="center">
            <template slot-scope="s">¥{{ s.row.amount }}</template>
          </el-table-column>
        </el-table>
      </el-card>
      <div slot="footer">
        <el-button @click="settlementDlgVisible=false">关闭</el-button>
        <el-button type="primary" @click="exportSettlement">导出结算报告</el-button>
      </div>
    </el-dialog>
  </el-card>
</template>

<script>
import request from "@/utils/request.js";
export default {
  name: "CashierSettlement",
  data() {
    return {
      todayStr: "",
      nowTimeStr: "",
      allRecords: [],
      filteredRecords: [],
      paymentFilter: "",
      todaySummary: { totalIncome: "0.00", regIncome: "0.00", drugCheckIncome: "0.00", orderCount: 0 },
      paymentBreakdown: [],
      settlementDlgVisible: false
    };
  },
  methods: {
    getTodayStr() {
      var d = new Date();
      return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
    },
    getTimeStr() {
      var d = new Date();
      return String(d.getHours()).padStart(2, "0") + ":" + String(d.getMinutes()).padStart(2, "0") + ":" + String(d.getSeconds()).padStart(2, "0");
    },
    async refreshData() {
      this.todayStr = this.getTodayStr();
      // Load today's orders that have been paid
      var today = this.todayStr;
      var start = today + " 00:00";
      var end = today + " 23:59";
      try {
        const res = await request.get("order/findOrdersByDate", { params: { start: start, end: end } });
        if (res.data.status === 200) {
          var orders = res.data.data || [];
          var paidOrders = orders.filter(function(o) { return o.oPriceState === 1; });

          // Load billing records for each paid order
          var allBilling = [];
          for (var i = 0; i < paidOrders.length; i++) {
            try {
              const br = await request.get("billing/findByOrder", { params: { oId: paidOrders[i].oId } });
              if (br.data.status === 200) {
                var records = br.data.data || [];
                allBilling = allBilling.concat(records);
              }
            } catch(e) {}
          }

          // Fallback: if no billing records but orders are paid, synthesize records from orders
          if (allBilling.length === 0 && paidOrders.length > 0) {
            paidOrders.forEach(function(o) {
              if (o.oRegistrationFee && o.oRegistrationFee > 0) {
                allBilling.push({
                  brId: "R" + o.oId, oId: o.oId, brType: "挂号费",
                  brAmount: o.oRegistrationFee, brPaymentMethod: o.oPaymentMethod || "现金",
                  brInvoiceNo: o.oInvoiceNo || "", brPayTime: o.oStart,
                  brOperator: "系统"
                });
              }
              if (o.oTotalPrice && o.oTotalPrice > 0) {
                allBilling.push({
                  brId: "D" + o.oId, oId: o.oId, brType: "药费+检查费",
                  brAmount: o.oTotalPrice, brPaymentMethod: o.oPaymentMethod || "现金",
                  brInvoiceNo: o.oInvoiceNo || "", brPayTime: o.oStart,
                  brOperator: "系统"
                });
              }
            });
          }

          this.allRecords = allBilling;

          // Calculate summary
          var totalIncome = 0, regIncome = 0, drugCheckIncome = 0;
          allBilling.forEach(function(b) {
            var amt = parseFloat(b.brAmount || 0);
            totalIncome += amt;
            if (b.brType === "挂号费") regIncome += amt;
            else drugCheckIncome += amt;
          });

          this.todaySummary = {
            totalIncome: totalIncome.toFixed(2),
            regIncome: regIncome.toFixed(2),
            drugCheckIncome: drugCheckIncome.toFixed(2),
            orderCount: allBilling.length
          };

          this.filterRecords();
          this.$nextTick(function() { this.initPaymentPie(); }.bind(this));
        }
      } catch(e) {
        this.$message.warning("暂未查询到今日收费数据");
      }
    },
    filterRecords() {
      if (this.paymentFilter) {
        this.filteredRecords = this.allRecords.filter(function(r) {
          return r.brPaymentMethod === this.paymentFilter;
        }.bind(this));
      } else {
        this.filteredRecords = this.allRecords.slice();
      }
    },
    initPaymentPie() {
      var chart = document.getElementById("paymentPieChart");
      if (!chart) return;
      var myChart = this.$echarts.init(chart);
      var methodMap = {};
      this.allRecords.forEach(function(r) {
        var m = r.brPaymentMethod || "其他";
        methodMap[m] = (methodMap[m] || 0) + parseFloat(r.brAmount || 0);
      });
      var data = Object.keys(methodMap).map(function(k) {
        return { name: k, value: methodMap[k] };
      });
      myChart.setOption({
        tooltip: { trigger: "item", formatter: "{b}: ¥{c} ({d}%)" },
        legend: { bottom: 0 },
        series: [{
          type: "pie", radius: ["35%", "60%"], center: ["50%", "45%"],
          data: data.length ? data : [{ name: "暂无数据", value: 1 }],
          label: { show: true, formatter: "{b}\n¥{c}" }
        }]
      });
    },
    dailySettlement() {
      if (this.allRecords.length === 0) return this.$message.warning("今日暂无收费记录");
      this.nowTimeStr = this.getTimeStr();
      var methodMap = {};
      var countMap = {};
      this.allRecords.forEach(function(r) {
        var m = r.brPaymentMethod || "其他";
        methodMap[m] = (methodMap[m] || 0) + parseFloat(r.brAmount || 0);
        countMap[m] = (countMap[m] || 0) + 1;
      });
      this.paymentBreakdown = Object.keys(methodMap).map(function(k) {
        return { method: k, count: countMap[k] || 0, amount: methodMap[k].toFixed(2) };
      });
      this.settlementDlgVisible = true;
    },
    exportCsv() {
      var list = this.filteredRecords.length ? this.filteredRecords : this.allRecords;
      if (list.length === 0) return this.$message.warning("暂无数据可导出");
      var csv = "﻿编号,订单号,收费类型,金额,支付方式,发票号,收费时间,操作员\n";
      list.forEach(function(r) {
        csv += (r.brId || "") + "," + (r.oId || "") + "," + (r.brType || "") + "," + (r.brAmount || 0) + "," + (r.brPaymentMethod || "") + "," + (r.brInvoiceNo || "") + "," + (r.brPayTime || "") + "," + (r.brOperator || "") + "\n";
      });
      var blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
      var a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = "收费记录_" + this.todayStr + ".csv";
      a.click();
      URL.revokeObjectURL(a.href);
    },
    exportSettlement() {
      var csv = "﻿结算日期," + this.todayStr + "\n结算时间," + this.nowTimeStr + "\n\n";
      csv += "收费总笔数," + this.todaySummary.orderCount + "\n总收入,¥" + this.todaySummary.totalIncome + "\n挂号费,¥" + this.todaySummary.regIncome + "\n药费+检查费,¥" + this.todaySummary.drugCheckIncome + "\n\n支付方式明细\n";
      csv += "支付方式,笔数,金额\n";
      this.paymentBreakdown.forEach(function(p) {
        csv += p.method + "," + p.count + ",¥" + p.amount + "\n";
      });
      var blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
      var a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = "日结报告_" + this.todayStr + ".csv";
      a.click();
      URL.revokeObjectURL(a.href);
    }
  },
  created() {
    this.refreshData();
  }
};
</script>
<style scoped>
.stat-card { border-radius: 8px; }
.stat-inner { display: flex; align-items: center; gap: 16px; padding: 8px 0; }
.stat-icon { width: 50px; height: 50px; border-radius: 10px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.stat-icon i { font-size: 24px; color: #fff; }
.stat-num { font-size: 22px; font-weight: 700; color: #303133; }
.stat-label { font-size: 13px; color: #909399; margin-top: 2px; }
</style>

